import { TROPE_EXTRAS } from "./trope-extras";

export type MoodPack = { keys: string[]; genres: string[]; label: string };
export type TropePack = { keys: string[]; titles: string[]; chips: string[]; kind?: "movie" | "series" };

/** Word-aware match so "art" does not hit "start" and "satire" still hits. */
export function keyMatches(haystack: string, key: string): boolean {
  const h = ` ${haystack.toLowerCase()} `;
  const k = key.toLowerCase().trim();
  if (!k) return false;
  if (k.includes(" ") || k.includes("-") || k.includes("'")) return h.includes(k);
  const escaped = k.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return new RegExp(`[^a-z0-9]${escaped}[^a-z0-9]`).test(h);
}

export function anyKeyMatches(haystack: string, keys: string[]): boolean {
  return keys.some((key) => keyMatches(haystack, key));
}

